// Android/JVM example: an upload that must tell the server it stopped.
suspend fun upload(session: Session, chunks: Flow<Chunk>) {
    try {
        chunks.collect { session.send(it) }
    } finally {
        withContext(NonCancellable) {
            // Small, bounded, and about releasing the session — not about
            // finishing the upload that was just cancelled.
            session.abort()
        }
    }
}

