import kotlin.concurrent.atomics.AtomicInt
import kotlin.concurrent.atomics.ExperimentalAtomicApi
import kotlin.concurrent.atomics.incrementAndFetch

@OptIn(ExperimentalAtomicApi::class)
class RequestCounter {
    private val served = AtomicInt(0)

    fun record() {
        served.incrementAndFetch()
    }

    fun snapshot(): Int = served.load()
}

private val mutex = Mutex()
private var balance = 0
private val ledger = mutableListOf<Entry>()

suspend fun apply(entry: Entry) {
    mutex.withLock {
        // The invariant is that these two agree, so both belong inside.
        balance += entry.amount
        ledger += entry
    }
}

// One result. Correct at the moment it returns, and silent afterwards.
suspend fun readTheme(): Theme

// Values over time. This API's contract: the current theme, and every later one.
fun observeTheme(): Flow<Theme>

class ThemeRepository(private val store: ThemeStore) {

    // One-shot: the caller wants the value now and will act on it once.
    suspend fun currentTheme(): Theme = store.read()

    // Observable: the caller stays in step with whatever is written next.
    fun themeChanges(): Flow<Theme> = store.themeChanges()

    // Also one-shot, and it should stay that way. A write is an action, not a stream.
    suspend fun setTheme(theme: Theme) = store.write(theme)
}

