// A deliberately plain listener API: register, get called back, unregister.
interface LocationListener {
    fun onLocation(value: Location)
}

interface LocationSource {
    fun register(listener: LocationListener)
    fun unregister(listener: LocationListener)
}

fun LocationSource.locations(): Flow<Location> = callbackFlow {
    val listener = object : LocationListener {
        override fun onLocation(value: Location) {
            // trySend cannot suspend, so it can fail: the buffer may be full, or
            // collection may already have ended. Dropping is a decision, not a default.
            trySend(value).onFailure { cause -> onLocationDropped(value, cause) }
        }
    }

    register(listener)

    awaitClose { unregister(listener) }
}
